<?php require_once __DIR__.'/includes/functions.php'; require_login(); $u=current_user(); $pdo=db(); $products=$pdo->query("SELECT * FROM products WHERE is_active=1 ORDER BY name")->fetchAll(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $pid=(int)$_POST['product_id'];$qty=max(1,(int)$_POST['quantity']);$size=$_POST['size']??'M';$color=trim($_POST['color']??'Black');$print=$_POST['printing']??'DTF';$notes=trim($_POST['notes']??'');$price=calculate_price($pid,$qty,$print);
if(!empty($_FILES['design']['name'])){$up=save_upload($_FILES['design'],'designs'); if(!$up['ok'])$error=$up['error'];}
if(!$error){$pdo->beginTransaction();try{$num='ORD-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(2)));$s=$pdo->prepare("INSERT INTO orders(order_number,customer_id,total_amount,status,notes) VALUES(?,?,?,'design_review',?)");$s->execute([$num,$u['id'],$price,$notes]);$oid=$pdo->lastInsertId();$pdo->prepare("INSERT INTO order_items(order_id,product_id,quantity,printing,unit_price) VALUES(?,?,?,?,?)")->execute([$oid,$pid,$qty,$print,$price/$qty]);$pdo->prepare("INSERT INTO order_sizes(order_id,size,quantity) VALUES(?,?,?)")->execute([$oid,$size,$qty]);if(isset($up['path']))$pdo->prepare("INSERT INTO uploads(order_id,user_id,type,file_path,original_name) VALUES(?,?, 'design',?,?)")->execute([$oid,$u['id'],$up['path'],$up['name']]);$pdo->prepare("INSERT INTO order_status_history(order_id,status,changed_by) VALUES(?,?,?)")->execute([$oid,'design_review',$u['id']]);$pdo->commit();redirect('customer/order-detail.php?id='.$oid);}catch(Throwable $e){$pdo->rollBack();$error='Gagal membuat pesanan: '.$e->getMessage();}}}
?><!doctype html><html lang="id"><head><?php include __DIR__.'/includes/head.php'; ?></head><body><?php include __DIR__.'/includes/header.php'; ?><main class="content narrow"><p class="eyebrow">CUSTOM ORDER</p><h1>Buat Pesanan</h1><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form class="panel form-grid" method="post" enctype="multipart/form-data"><label>Produk<select name="product_id" id="product"><?php foreach($products as $p):?><option value="<?=$p['id']?>" data-price="<?=$p['base_price']?>"><?=e($p['name'])?> — Rp <?=number_format($p['base_price'],0,',','.')?></option><?php endforeach;?></select></label><label>Jumlah<input id="qty" type="number" name="quantity" min="1" value="12"></label><label>Ukuran<select name="size"><option>S</option><option selected>M</option><option>L</option><option>XL</option><option>XXL</option></select></label><label>Warna<input name="color" value="Black"></label><label>Jenis printing<select name="printing"><option>DTF</option><option>DTG</option><option>Screen Printing</option><option>Embroidery</option></select></label><label>Upload desain<input type="file" name="design" accept=".jpg,.jpeg,.png,.pdf"></label><label class="full">Catatan<textarea name="notes" rows="4"></textarea></label><div class="price full">Estimasi: <strong id="total">Rp 0</strong></div><button class="btn full">Buat Pesanan</button></form></main><script>const p=document.querySelector('#product'),q=document.querySelector('#qty'),t=document.querySelector('#total');function calc(){t.textContent='Rp '+(Number(p.selectedOptions[0].dataset.price||0)*Number(q.value||1)).toLocaleString('id-ID')}p.onchange=q.oninput=calc;calc();</script></body></html>